"""Atari 8-bit memory snapshots (.xlm): walk the ANTIC display list."""
import struct

# Number of ANTIC scan lines generated by one mode-line instruction.
LINES = {
    2: 8,
    3: 10,
    4: 8,
    5: 16,
    6: 8,
    7: 16,
    8: 8,
    9: 4,
    10: 4,
    11: 2,
    12: 1,
    13: 2,
    14: 1,
    15: 1,
}

# Display-data bytes fetched by one instruction at normal DMACTL width.
WIDTH = {
    2: 40,
    3: 40,
    4: 40,
    5: 40,
    6: 20,
    7: 20,
    8: 10,
    9: 10,
    10: 20,
    11: 20,
    12: 20,
    13: 40,
    14: 40,
    15: 40,
}

# DMACTL playfield codes are off, narrow (32 mode-2 bytes), normal (40),
# and wide (48).  Other ANTIC widths scale by the same 4/5 and 6/5 factors.
WIDTH_SCALE_NUM = {1: 4, 2: 5, 3: 6}
LIMIT = 2000


class DisplayListError(ValueError):
    pass


def parse(data):
    if len(data) != 9 + 65536 or data[:6] != b"XLMEM\x00":
        raise DisplayListError("not a memory snapshot")
    pc, dmactl = struct.unpack_from("<HB", data, 6)
    mem = data[9:]
    width_code = dmactl & 3
    if width_code == 0:
        raise DisplayListError("playfield DMA is off")

    def fetch():
        nonlocal pc
        b = mem[pc]
        pc = (pc + 1) & 0xFFFF
        return b

    scan = mode_lines = blank_lines = dli = lms_count = jumps = screen = 0
    msc = 0
    modes = {}
    ranges = []

    def add_range(start, end):
        # End is kept modulo 64 KiB.  A wrapped interval is written as, for
        # example, fff8-0020.
        if ranges and ranges[-1][1] == start:
            ranges[-1][1] = end
        else:
            ranges.append([start, end])

    for _ in range(LIMIT):
        op = fetch()
        mode = op & 15

        if op & 0x80:
            dli += 1

        if mode == 0:
            n = ((op >> 4) & 7) + 1
            scan += n
            blank_lines += n
            continue

        if mode == 1:
            target = fetch() | (fetch() << 8)
            jumps += 1
            if op & 0x40:
                # JVB ends the display list after loading its target.
                break
            # JMP continues at its absolute target.
            pc = target
            continue

        if op & 0x40:
            msc = fetch() | (fetch() << 8)
            lms_count += 1

        n = WIDTH[mode] * WIDTH_SCALE_NUM[width_code] // 5
        if op & 0x10:
            # Horizontal fine scrolling needs one extra display-data byte.
            n += 1

        start = msc
        msc = (msc + n) & 0xFFFF
        add_range(start, msc)
        screen += n
        mode_lines += 1
        scan += LINES[mode]
        modes[mode] = modes.get(mode, 0) + 1
    else:
        raise DisplayListError("display list never reaches a JVB")
    return {"scanlines": scan, "mode_lines": mode_lines, "blank_lines": blank_lines, "dli": dli,
            "lms": lms_count, "jumps": jumps, "screen_bytes": screen,
            "modes": {"%X" % m: modes[m] for m in sorted(modes)},
            "fetch": ["%04x-%04x" % (a, b) for a, b in ranges]}
